def solve_all_interval_series(n):
    def backtrack(current_series, used_numbers, used_differences):
        if len(current_series) == n:
            return current_series

        last_val = current_series[-1]
        for next_val in range(n):
            if next_val not in used_numbers:
                diff = abs(next_val - last_val)
                if diff != 0 and diff not in used_differences:
                    used_numbers.add(next_val)
                    used_differences.add(diff)
                    current_series.append(next_val)

                    result = backtrack(current_series, used_numbers, used_differences)
                    if result:
                        return result

                    current_series.pop()
                    used_differences.remove(diff)
                    used_numbers.remove(next_val)
        return None

    for start_node in range(n):
        result = backtrack([start_node], {start_node}, set())
        if result:
            return result
    return None

n = 13
solution = solve_all_interval_series(n)
print(solution)

def check_all_interval_series(series):
    n = len(series)
    if sorted(series) != list(range(n)):
        return False, "Not a permutation of 0 to n-1"

    differences = []
    for i in range(n - 1):
        diff = abs(series[i+1] - series[i])
        differences.append(diff)

    if sorted(differences) != list(range(1, n)):
        return False, f"Differences are not a permutation of 1 to {n-1}: {sorted(differences)}"

    return True, "Valid"

series = [0, 12, 1, 11, 2, 10, 3, 9, 4, 8, 5, 7, 6]
print(check_all_interval_series(series))
